package com.sabit.duelloquiz.licenses

import android.content.Context
import com.sabit.duelloquiz.R
import com.sabit.duelloquiz.core.data.licenses.BundledLicenseFiles
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject

/**
 * `R.raw.aboutlibraries` is generated by the AboutLibraries plugin of this module for every
 * variant; the Nunito OFL text is an asset of :core:designsystem.
 */
internal class AndroidBundledLicenseFiles @Inject constructor(
    @param:ApplicationContext private val context: Context,
) : BundledLicenseFiles {

    override fun librariesJson(): String =
        context.resources.openRawResource(R.raw.aboutlibraries).bufferedReader().use { it.readText() }

    override fun nunitoLicenseText(): String? = runCatching {
        context.assets.open(NUNITO_LICENSE_ASSET).bufferedReader().use { it.readText() }
    }.getOrNull()

    private companion object {
        /** Copied from core/designsystem/third_party/nunito/OFL.txt at build time. */
        const val NUNITO_LICENSE_ASSET = "licenses/nunito/OFL.txt"
    }
}
